// The theme's roles, finishes, radii, focus and motion, read from `theme.json` and `finishes.json`.
// From NSH's examples/nsh-gallery-ui (Apache-2.0, © Longbridge; see NOTICE): yours to change.
import type { AnimatedValue, TextStyle, Theme, Tokens, ViewStyle } from "nsh";
import {
  colorScheme,
  computed,
  createAnimatedValue,
  Easing,
  effect,
  platform,
  reduceMotion,
  setTheme,
  signal,
  token,
} from "nsh";

import finishes from "./finishes.json";

/**
 * The Terminal idiom (`nsh`'s internal module, so not a public API): a
 * terminal program leaves out what it cannot draw well (charts,
 * sparklines, decorative icons and art, window chrome), puts on one row
 * what other platforms stack, and spaces in whole rows.
 */
export const terminal = platform.idiom === "terminal";

/**
 * One row and one column of the terminal grid, in points (a Cell is 16 by 8
 * points): the terminal's line height and its unit of spacing. This
 * library's own, over `nsh`'s internal Cell metrics; everywhere else the
 * grid keeps two columns to a Cell.
 */
export const TERMINAL_ROW = 16;
export const TERMINAL_COLUMN = 8;

/** The gap the terminal's layout makes two columns (it makes any smaller
 * gap one): between neighbours that are words, such as icon buttons shown
 * as their labels, so they read apart. */
export const TERMINAL_GAP = 24;

/** Whether the app shows its dark palette; reactive: reading it subscribes. */
export const isDark = () => colorScheme() !== "light";

/** A surface's finish: a gradient over its color and its shadows. */
export interface Finish {
  backgroundColor?: string;
  backgroundImage?: string;
  boxShadow: string;
  borderColor?: string;
  backdropFilter?: string;
}

/** The finishes' roles: the keys of `finishes.json`'s two appearances. */
export type FinishRole =
  | "card"
  | "inset"
  | "field"
  | "raised"
  | "hover"
  | "pressed"
  | "light"
  | "accent"
  | "track"
  | "fill"
  | "knob"
  | "knobOn"
  | "handle"
  | "pill"
  | "thumb"
  | "on"
  | "chip"
  | "glass"
  | "menu"
  | "groove";

/** What a theme's `finishes.json` holds: its style, then its finishes, one set per appearance. */
export interface Finishes extends Style {
  press: Press;
  dark: Record<FinishRole, Finish>;
  light: Record<FinishRole, Finish>;
}

/** A value for each tier: a pointer's (a desktop) and a touch screen's. */
export interface Tiered<T> {
  pointer: T;
  touch: T;
}

/** One type role: its size and line height per tier, its weight (`"400"`), its tracking in points. */
export interface TypeRole {
  size: Tiered<number>;
  line: Tiered<number>;
  weight: string;
  tracking: number;
}

/** The sizes of a list of controls in one tier: see `controlSize`. */
export interface ControlSizes {
  row: number;
  padding: number;
  gap: number;
  control: number;
  corner: number;
  check: number;
  dot: number;
  tabs: number;
  line: number;
  clear: number;
  switch: string;
}

/** A page's density in one tier: see `density`. */
export interface DensitySizes {
  row: number;
  pad: number;
  gap: number;
  surface: number;
}

/** Three steps of one size, small to large. */
export interface Steps {
  sm: number;
  md: number;
  lg: number;
}

/** A spring of `motion`: a unit mass's stiffness and damping. */
export interface Spring {
  stiffness: number;
  damping: number;
}

/**
 * The style of a theme: what `finishes.json` states beside its finishes, the same keys in every
 * theme (`check:theme`). A string that names one of a list (a weight, a curve, an easing, an
 * indicator) is typed as a string here, since a JSON import is; `check:theme` holds the list
 * (`scripts/theme/style.ts`). `docs/specs/native-themes.md` §3.2 says what each key is.
 */
export interface Style {
  type: {
    /** `null` is the system font. */
    family: string | null;
    caption: TypeRole;
    detail: TypeRole;
    body: TypeRole;
    label: TypeRole;
    title: TypeRole;
    headline: TypeRole;
    display: TypeRole;
  };
  shape: {
    control: number;
    field: number;
    chip: number;
    card: number;
    overlay: number;
    dialog: number;
    sheet: number;
    inset: number;
    curve: string;
    corners: { field: string };
  };
  size: {
    hit: Tiered<number>;
    density: Tiered<DensitySizes>;
    control: Tiered<ControlSizes>;
    height: Tiered<Steps>;
  };
  stroke: { hairline: number; control: number; indicator: number };
  focus: { style: string; width: number; offset: number };
  state: {
    overlay: { hover: number; focus: number; pressed: number; dragged: number };
    ripple: boolean;
    pressedOpacity: number;
    disabled: { content: number; container: number };
  };
  motion: {
    press: Spring;
    settle: Spring;
    control: Spring;
    move: Spring;
    enter: { duration: number; easing: string };
    /** A rejected value's shake, the length of `nsh`'s `play("shake")` preset. */
    shake: { duration: number };
  };
  icon: { size: Tiered<Steps> };
  indicator: { tabs: string; nav: string; field: string };
}

/**
 * One theme an app can switch to while it runs (`selectTheme`): the id an
 * app stores to bring it back, the name a list of them shows, and the
 * content of the two files a theme is.
 */
export interface AppTheme {
  /** The id an app stores and compares: `"shadcn"`. */
  id: string;
  /** The name a list of themes shows: `"shadcn neutral"`. */
  label: string;
  /** `theme.json`'s content: the tokens `setTheme` takes. */
  theme: Theme;
  /** `finishes.json`'s content. */
  finishes: Finishes;
}

/** How far a press sinks a control in a theme, in both appearances. */
export interface Press {
  /**
   * The scale a pressed control lands on: `0.97` for the default theme, where a press is a small
   * sink; `1` for a theme whose surfaces are flat and draw no press of their own (shadcn's).
   */
  scale: number;
}

/** The build-time finishes: `finishes.json` beside this file (the app's `nsh-ui.json` names the theme they belong to). */
const builtIn: Finishes = finishes;

/** The theme `selectTheme` put in; `null` while the app shows its build-time one. */
const selected = signal<AppTheme | null>(null);

/** The finishes in use: the selected theme's, else the build-time ones. Reactive: reading it subscribes. */
const finishesOf = (): Finishes => selected()?.finishes ?? builtIn;

/**
 * The style in use (type, shape, size, motion…): the selected theme's, else the build-time one's.
 * Reactive: reading it in JSX, a `draw` or an effect follows `selectTheme`.
 */
export const style = (): Style => finishesOf();

/**
 * An object whose properties are read from the style in use: one getter per key, so `density.row`
 * follows `selectTheme` as a plain value would not, and the object still spreads. Each key is a
 * `computed` made here, at import (one made inside a component would be disposed with it), so what
 * reads a key re-runs only when its value changes, not whenever a theme is selected.
 */
export function reactive<T extends object>(keys: readonly (keyof T)[], read: () => T): T {
  const out = {} as T;
  for (const key of keys) {
    const value = computed(() => read()[key]);
    Object.defineProperty(out, key, { enumerable: true, get: () => value() });
  }
  return out;
}

/** The tier a pointer's screen (a desktop) or a touch screen reads: `platform.desktop`, fixed for the run. */
export const tier: "pointer" | "touch" = platform.desktop ? "pointer" : "touch";

/** The one relative color a finish writes: a token's color at another alpha. */
const relative = /oklch\(from var\(--([a-z0-9-]+)\) l c h \/ ([\d.]+)\)/g;

/** A token's color, `#rrggbbaa` as `token` gives it, at another alpha. */
const atAlpha = (color: string, a: number) =>
  `${color.slice(0, 7)}${Math.round(a * 255)
    .toString(16)
    .padStart(2, "0")}`;

/**
 * A finish's strings name the theme's tokens instead of writing their colors (`var(--raised)`, an
 * alias): the finishes keep one shape in every theme while the colors they draw are the theme's.
 * `token` reads the same token the rest of the theme does, so an alias follows the appearance and
 * the theme `selectTheme` put in, and a `var()` anywhere in a gradient or a shadow resolves with it.
 *
 * A token named at another alpha (`oklch(from var(--card) l c h / 0.78)`, the one relative color a
 * finish writes) resolves to that token's color with the alpha replaced: NSH reads these strings
 * as plain CSS and has no relative color syntax. It goes through `token` rather than reading the
 * theme file, so this module imports nothing but `finishes.json`: it is `lib/theme.ts` in an app,
 * whose `theme.json` sits at its root.
 */
const alias = (value: string): string =>
  value
    .replace(relative, (whole, name: string, a: string) => {
      const color = token(name as keyof Tokens);
      return typeof color === "string" ? atAlpha(color, Number(a)) : whole;
    })
    .replace(/var\(--([a-z0-9-]+)\)/g, (whole, name: string) => {
      const color = token(name as keyof Tokens);
      return typeof color === "string" ? color : whole;
    });

/** What one finish role has resolved: the theme it resolved from, and the strings per appearance. */
type Resolved = { source: AppTheme | null; light: Finish; dark: Finish };

/**
 * What `alias` has resolved, per role. A finished string is one shadow, gradient or color of
 * `finishes.json` with the theme's tokens put in, so it is the same string on every read until the
 * theme or the appearance changes: a surface that reads its finishes once per binding should pay for
 * the regular expressions once, not once per read.
 *
 * Keyed by the theme the strings came from, not emptied by `selectTheme`: that sets the theme and
 * then the finishes, and a reader may run between the two, so an entry is only ever used for the
 * theme it was resolved from. The appearance picks which half a read takes, and it is the other
 * half of the same theme.
 */
const resolved = new Map<FinishRole, Resolved>();

/**
 * An object whose getters read one finish role of the finishes in use, in
 * the appearance shown: shadows and gradients are no design tokens, so they
 * stay here while every color is the theme's, by alias. Reading one
 * subscribes to the appearance and to the theme `selectTheme` put in.
 */
function themed(role: FinishRole): Finish {
  const kept: Resolved = { source: null, light: {} as Finish, dark: {} as Finish };
  resolved.set(role, kept);
  const out = {} as Finish;
  for (const key of Object.keys(builtIn.dark[role]) as (keyof Finish)[]) {
    Object.defineProperty(out, key, {
      enumerable: true,
      get: () => {
        const source = selected();
        if (kept.source !== source) {
          kept.source = source;
          kept.light = {} as Finish;
          kept.dark = {} as Finish;
        }
        const finishes = source?.finishes ?? builtIn;
        const dark = isDark();
        const value = (dark ? finishes.dark : finishes.light)[role][key];
        if (value === undefined) return value;
        const cache = dark ? kept.dark : kept.light;
        const done = cache[key];
        if (done !== undefined) return done;
        const finished = alias(value);
        cache[key] = finished;
        return finished;
      },
    });
  }
  return out;
}

/** The palette's roles: one color each, a token of the theme's `theme.json`. */
export interface Palette {
  /** The page behind the cards. */
  background: string;
  /** A card. */
  card: string;
  /** A surface inside a card. */
  inset: string;
  /** A control on a card (buttons, fields, tracks). */
  raised: string;
  /** An input's well: below the card and the insets it sits on. */
  field: string;
  /** An input's edge. */
  input: string;
  /** The hairline round what needs an edge (a card, a well, a divider). */
  border: string;
  /** Hairlines inside insets. */
  line: string;
  /** The edge a filled pane draws (a primary button, a chosen run, a chip): the accent a step down,
   * or `border` where the theme's fill is flat. */
  brandEdge: string;
  /** The hairline round a glass surface (a raised pane, a track's thumb, a popover): Solid Glass' own
   * line, `border` in a flat theme. */
  glassEdge: string;
  /** Body text. */
  foreground: string;
  /** Secondary text: a detail, a caption. */
  mutedForeground: string;
  /** What recedes the furthest: a placeholder, an icon at rest. */
  faint: string;
  /** The accent as a foreground: text, icons, lines, small marks. */
  brand: string;
  /** The accent as a fill (buttons, bubbles), with `onBrand` on it. */
  brandFill: string;
  /** Text on the accent fill. */
  onBrand: string;
  /** The main action's fill (the theme's `primary`): the citrus, in both appearances. */
  primary: string;
  /** Text on `primary`. */
  primaryForeground: string;
  /** The app's sidebar, beside the page. */
  sidebar: string;
  /** The selected row of the sidebar. */
  sidebarAccent: string;
  /** The sidebar's edge and the toolbar's hairline. */
  sidebarBorder: string;
  /** A switch's track when off. */
  track: string;
  /** A switch's knob when off. */
  knob: string;
  /** Code inside insets. */
  code: string;
  /** The tone colors: information, a warning, a failure, a gain, a loss. */
  info: string;
  warn: string;
  destructive: string;
  up: string;
  down: string;
  /** White ink on a photograph or any other surface that is not the theme's. It does not flip. */
  onMedia: string;
  /**
   * Dark ink on a light chart tile. A dark tile uses `on-media` instead (`data-dark:`), because
   * `nsh/base` marks a plot cell dark from its own OKLab lightness, not from the appearance.
   */
  chartForeground: string;
}

/** An object whose getters read the theme's tokens: reads in a reactive
 * scope (JSX, a `draw`, an effect) follow the appearance and the theme. */
function tokens<K extends string>(names: Record<K, keyof Tokens>): Record<K, string> {
  const out = {} as Record<K, string>;
  for (const key of Object.keys(names) as K[]) {
    Object.defineProperty(out, key, { enumerable: true, get: () => token(names[key]) });
  }
  return out;
}

/**
 * The palette in use, read from the theme's tokens: reactive, so reading it
 * in JSX, a `draw` or an `effect` follows the appearance and the theme
 * `selectTheme` put in.
 */
export const colors: Palette = tokens<keyof Palette>({
  background: "background",
  card: "card",
  inset: "inset",
  raised: "raised",
  field: "field",
  input: "input",
  border: "border",
  line: "line",
  brandEdge: "brand-edge",
  glassEdge: "glass-edge",
  foreground: "foreground",
  mutedForeground: "muted-foreground",
  faint: "faint",
  brand: "brand",
  brandFill: "brand-fill",
  onBrand: "on-brand",
  primary: "primary",
  primaryForeground: "primary-foreground",
  sidebar: "sidebar",
  sidebarAccent: "sidebar-accent",
  sidebarBorder: "sidebar-border",
  track: "track",
  knob: "knob",
  code: "code",
  info: "info",
  warn: "warn",
  destructive: "destructive",
  up: "up",
  down: "down",
  onMedia: "on-media",
  chartForeground: "chart-foreground",
});

/**
 * The window buttons an app draws for a frameless window on macOS (the
 * traffic lights): close, minimize and zoom in the system's hues, the
 * glyphs' ink over them, their hairline edge, and `off`, all three while
 * the window is in the background.
 */
export const windowControls = tokens<"close" | "minimize" | "zoom" | "ink" | "edge" | "off">({
  close: "window-close",
  minimize: "window-minimize",
  zoom: "window-zoom",
  ink: "window-control-ink",
  edge: "window-control-edge",
  off: "window-control-off",
});

/**
 * `color` at opacity `a` (0 to 1): a `color-mix` over nothing, for a fill or a text color that is
 * the theme's at a lighter weight. Clamped, so a ratio past its ends is still a color.
 */
export function alpha(color: string, a: number): string {
  return `color-mix(in srgb, ${color} ${Math.min(Math.max(a, 0), 1) * 100}%, transparent)`;
}

/** The charts' series colors, in order (`theme.json`'s `chart-1` to
 * `chart-5`): the brand's citrus first, then graphite from dark to light,
 * so one series leads and the rest stay as quiet as the interface. */
export const chart = tokens({
  chart1: "chart-1",
  chart2: "chart-2",
  chart3: "chart-3",
  chart4: "chart-4",
  chart5: "chart-5",
});

/** Translucent tints of the tones, for fills behind text. */
export const tints = tokens({
  brand: "brand-tint",
  info: "info-tint",
  warn: "warn-tint",
  destructive: "destructive-tint",
  up: "up-tint",
  down: "down-tint",
});

/**
 * Light and depth, kept quiet: one-color edges (corners join cleanly), a
 * hard 1-point drop under what stands up and a 1-point inner shade in what
 * is sunk; only floating surfaces (menus, glass) cast a soft
 * shadow. `hover` and `pressed` are a raised control's states, `fill` a
 * slider's or a progress bar's run of the accent; `knob` a switch's knob on its
 * sunk track, `knobOn` the white one with an olive edge on the citrus.
 * `handle` is a slider's thumb, the knob's twin here; a theme whose thumb
 * wears an edge the switch's knob does not (shadcn's `border-primary`) tells
 * them apart. `thumb` is a segmented control's or a tab strip's selected segment on
 * its sunk track: the raised fill dark; white with a soft drop light, where
 * the raised fill is all but the track's color.
 * `on` is what stays on (a toggle, a chosen tool, a selected button): a
 * fill that stands off every surface it sits on, and off a raised control
 * at rest, further than a hover does, so on and off read apart at a
 * glance. Dark, a step lighter than the raised fill; light, where a raised
 * fill is all but the color of the card and the inset under it, a deeper
 * neutral with an edge. `groove` is a hairline's lip of light under it, a
 * menu's separator cut into the surface.
 */
export const finish: Record<FinishRole, Finish> = {
  card: themed("card"),
  inset: themed("inset"),
  field: themed("field"),
  raised: themed("raised"),
  hover: themed("hover"),
  pressed: themed("pressed"),
  light: themed("light"),
  accent: themed("accent"),
  track: themed("track"),
  fill: themed("fill"),
  knob: themed("knob"),
  knobOn: themed("knobOn"),
  handle: themed("handle"),
  pill: themed("pill"),
  thumb: themed("thumb"),
  on: themed("on"),
  chip: themed("chip"),
  glass: themed("glass"),
  menu: themed("menu"),
  groove: themed("groove"),
};

/**
 * How far a press sinks a control, as the theme in use says (`finishes.json`'s `press.scale`):
 * `0.97` where a press is a small sink, `1` where the theme draws none. A control that sinks
 * deeper than that names its own scale (`pressSink(0.9)`); a theme of `1` turns every sink off.
 * Reactive: reading it follows `selectTheme`.
 */
export const press = {
  get scale() {
    return finishesOf().press.scale;
  },
};

/**
 * Switch the app to `theme` while it runs: the tokens first (`setTheme`),
 * then its finishes, so every component on screen redraws with both on the
 * next frame. `null` goes back to the theme the app was built with
 * (`nsh.json`'s `theme.json`, and `finishes.json` beside this file).
 *
 * A theme NSH refuses to read (a color it does not know) throws
 * `TypeError` and leaves the app as it was: the finishes follow the tokens
 * only once they are in.
 */
export function selectTheme(theme: AppTheme | null): void {
  setTheme(theme ? withFamily(theme) : null);
  selected.set(theme);
}

/**
 * The theme's tokens with `font-sans` (the font of every text that names no family) set from the
 * style's `type.family`: `null` leaves it to `theme.json` (the system font unless it names one),
 * `"sans"` is that token as it stands, `"rounded"` the rounded system font, `"mono"` the theme's
 * `font-mono`.
 */
function withFamily({ theme, finishes }: AppTheme): Theme {
  const { family } = finishes.type;
  if (family === null || family === "sans") return theme;
  const cssVars = theme.cssVars ?? {};
  const sans = family === "rounded" ? "ui-rounded" : (cssVars.theme?.["font-mono"] ?? "monospace");
  return { ...theme, cssVars: { ...cssVars, theme: { ...cssVars.theme, "font-sans": sans } } };
}

/**
 * The `id` of the theme the app shows (`selectTheme`), or `null` while it
 * shows its build-time one — the runtime cannot read `nsh-ui.json`. Reactive:
 * reading it subscribes.
 */
export function currentTheme(): string | null {
  const theme = selected();
  return theme === null ? null : theme.id;
}

export type Tone = "neutral" | "accent" | "info" | "warn" | "destructive" | "up" | "down";

/**
 * The color of a tone. `accent` is the brand ink: the tone keeps its name, and the palette key is
 * the token (`brand`).
 */
export const toneColor = (tone: Tone) =>
  tone === "neutral" ? colors.mutedForeground : tone === "accent" ? colors.brand : colors[tone];

/**
 * The tint of a tone. `accent` reads `tints.brand` (the `brand-tint` token); the other tones share
 * a key with `colors`.
 */
export const toneTint = (tone: Tone) =>
  tone === "neutral" ? colors.raised : tone === "accent" ? tints.brand : tints[tone];

/** The monospaced family, for code (API names, identifiers): the theme's
 * `font-mono`, which is also what the `font-mono` class and code in a `TextView`
 * draw in. Called where the style is built, so it follows `selectTheme`; a
 * theme that names no family gets NSH's `monospace`, the system's own. Figures
 * use the system font with tabular numbers instead. */
export const mono = () => token("font-mono");

/** A type role of `finishes.json`'s `type`: every one but the family. */
export type TypeName = Exclude<keyof Style["type"], "family">;

/**
 * One facet of a type role, read from the style in use (reactive: reading it in JSX, a `draw` or
 * an effect follows `selectTheme`). A component reads only the facets it set before, so text that
 * leaves its weight or line height to the text around it still does:
 * `style={{ fontSize: font.size("label"), fontWeight: font.weight("label") }}`.
 * `size` and `line` take the tier of the screen (`tier`).
 */
export const font = {
  size: (role: TypeName) => style().type[role].size[tier],
  line: (role: TypeName) => style().type[role].line[tier],
  weight: (role: TypeName) => style().type[role].weight as NonNullable<TextStyle["fontWeight"]>,
  tracking: (role: TypeName) => style().type[role].tracking,
};

/**
 * The corner radii by role (`finishes.json`'s `shape`), read from the style in use: what the
 * component is picks the role (`control` a button, `field` an input, `chip` a badge, `card` a card,
 * `overlay` a menu or a popup, `dialog`, `sheet`, `inset` a well inside a card). Reactive: reading
 * one in JSX, a `draw` or an effect follows `selectTheme`.
 */
export const shape = {
  get control() {
    return style().shape.control;
  },
  get field() {
    return style().shape.field;
  },
  get chip() {
    return style().shape.chip;
  },
  get card() {
    return style().shape.card;
  },
  get overlay() {
    return style().shape.overlay;
  },
  get dialog() {
    return style().shape.dialog;
  },
  get sheet() {
    return style().shape.sheet;
  },
  get inset() {
    return style().shape.inset;
  },
};

/** Line widths in points (`finishes.json`'s `stroke`): `hairline` a surface's edge and a divider, `control` a control's edge, `indicator` a selection's bar. The focus ring's width is `focus.width`. */
export const stroke = {
  get hairline() {
    return style().stroke.hairline;
  },
  get control() {
    return style().stroke.control;
  },
  get indicator() {
    return style().stroke.indicator;
  },
};

/**
 * How far a control fades (`finishes.json`'s `state`): `pressed` is the opacity of a pressed
 * control (`pressedOpacity`), `disabled` and `disabledContainer` those of a disabled control's
 * content (the whole control, when it is drawn as one) and of its container.
 */
export const dimmed = {
  get pressed() {
    return style().state.pressedOpacity;
  },
  get disabled() {
    return style().state.disabled.content;
  },
  get disabledContainer() {
    return style().state.disabled.container;
  },
};

/**
 * The state layer of a theme that draws its hover, focus, press and drag as a wash of the text
 * color over the surface (`state.overlay`, an opacity; Material's): a gradient of that one color,
 * to spread over a control's style. A theme whose overlay is 0 (the default: its states swap
 * the surface's finish) draws none, so this is an empty style.
 */
export function stateLayer(kind: keyof Style["state"]["overlay"]): ViewStyle {
  const opacity = style().state.overlay[kind];
  if (opacity <= 0) return {};
  const wash = atAlpha(token("foreground") as string, opacity);
  return { backgroundImage: `linear-gradient(180deg, ${wash} 0%, ${wash} 100%)` };
}

/** The smallest target a finger or a pointer gets (`size.hit` of the tier): 0 adds none. */
export const hitTarget = (): number => style().size.hit[tier];

/** A button's height by size (`size.height` of the tier). */
export const controlHeight = {
  get sm() {
    return style().size.height[tier].sm;
  },
  get md() {
    return style().size.height[tier].md;
  },
  get lg() {
    return style().size.height[tier].lg;
  },
};

/** An icon's side by size (`icon.size` of the tier). */
export const iconSize = {
  get sm() {
    return style().icon.size[tier].sm;
  },
  get md() {
    return style().icon.size[tier].md;
  },
  get lg() {
    return style().icon.size[tier].lg;
  },
};

/** Every corner that reads a theme radius is continuous: the curve macOS
 * draws, not a circular arc. */
export const cornerCurve: ViewStyle = {
  get borderCurve() {
    return style().shape.curve === "circular" ? "circular" : "continuous";
  },
};

/**
 * A corner on one of the theme's radii, with the curve they all share. `inset` makes it concentric:
 * a surface drawn `inset` points inside another takes the outer radius less `inset`, never below 0.
 */
export function rounded(radius: number, inset = 0): ViewStyle {
  return { borderRadius: Math.max(radius - inset, 0), ...cornerCurve };
}

/** The system header's colors on every page (iOS, Android). */
export const header = {
  get headerStyle() {
    return {
      backgroundColor: colors.background,
      color: colors.foreground,
      tintColor: colors.brand,
    };
  },
};

/**
 * A spring that reads its stiffness and damping from the style in use whenever a value springs to
 * its target, so a control made before `selectTheme` still moves as the new theme says.
 */
const spring = (read: () => Spring): Spring => reactive<Spring>(["stiffness", "damping"], read);

/** The easings a theme names (`motion.enter.easing`): the curve is code, the name is data. */
const easings = {
  "out-cubic": Easing.out(Easing.cubic),
  "in-cubic": Easing.in(Easing.cubic),
  "in-out-cubic": Easing.inOut(Easing.cubic),
};

/**
 * The motion every control shares: quick, slightly springy. `control` and
 * `move` are gpui-kit's `spring_control` (a 180 ms response, no overshoot:
 * a mark or a fill coming and going) and `spring_move` (280 ms, a damping
 * ratio of 0.85: a thumb or an indicator traveling) as a unit mass's
 * stiffness (2π / response)² and damping 2 · ratio · 2π / response.
 */
export const motion = {
  press: spring(() => style().motion.press),
  settle: spring(() => style().motion.settle),
  control: spring(() => style().motion.control),
  move: spring(() => style().motion.move),
  get enter() {
    const { duration, easing } = style().motion.enter;
    return { duration, easing: easings[easing as keyof typeof easings] };
  },
  get shake() {
    return { duration: style().motion.shake.duration };
  },
};

/**
 * An animated value that springs to `target` each time it changes (a
 * control's state: 1 while on, 0 while off), natively: JS only starts each
 * spring. A change mid-way turns it from where it is, with its velocity;
 * with reduced motion it lands at once. For discrete changes only: what
 * the pointer drives (a dragged thumb, a hover's place) is set in the same
 * frame, never sprung toward the pointer.
 */
export function follow(
  target: () => number,
  spring: { stiffness: number; damping: number } = motion.control,
): AnimatedValue {
  const v = createAnimatedValue(target());
  let shown = target();
  effect(() => {
    const next = target();
    if (next === shown) return;
    shown = next;
    if (reduceMotion()) v.set(next);
    else v.spring(next, spring);
  });
  return v;
}

/**
 * A pressable under the pointer (`hoverStyle`): the theme's `hover` (here a
 * whisper of the text color over its surface, quieter than pressed and than
 * selected; shadcn's `accent`). Leave it off a disabled control and off a
 * selected one, whose own fill shows.
 */
export const hovered = (): ViewStyle => ({
  backgroundColor: token("hover"),
  ...stateLayer("hover"),
});

/**
 * The keyboard focus (`focusVisibleStyle`: not after a click or a tap): the
 * edge turns the theme's `ring` and a halo of `ring-halo` (`focus.width` points, 3 by
 * default: shadcn/ui's `ring-3`) lies around the view (a faint wash of the ring; shadcn's
 * `ring/50`), `offset` points out from the edge (`focus.offset` when not given). A theme whose
 * `focus.style` is `outline` draws the ring itself, not its halo, as the outline.
 */
export const focusRing = (offset?: number): ViewStyle => {
  const { style: look, width, offset: base } = style().focus;
  return {
    borderColor: token("ring"),
    outlineStyle: "solid",
    outlineWidth: width,
    outlineColor: token(look === "outline" ? "ring" : "ring-halo"),
    outlineOffset: offset ?? base,
  };
};

/*
 * Below: this library's own, with no upstream origin.
 */

/**
 * A theme's fill for a run, a bar or a slider's range: its gradient, and the color under it. The
 * gradient carries the color (a flat theme repeats one color in both stops); the theme keeps its
 * `backgroundColor` transparent, since a color under the gradient shows through and tints the run.
 */
export function fillStyle(): ViewStyle {
  return {
    backgroundColor: finish.fill.backgroundColor,
    backgroundImage: finish.fill.backgroundImage,
  };
}

/**
 * A rail's edge: a `width`-point inset line of `borderColor` inside the theme's `boxShadow`,
 * whichever of the two the theme gives. `finishes.json` may write `boxShadow: "none"` or leave
 * the color out, and a rail that joined the absent one after a comma would void the whole
 * declaration (`none, inset …` is not a shadow).
 */
export function insetEdge(
  borderColor: string | undefined,
  boxShadow: string | undefined,
  width = 1,
): string {
  const line = borderColor ? `inset 0 0 0 ${width}px ${borderColor}` : undefined;
  const shade = boxShadow && boxShadow !== "none" ? boxShadow : undefined;
  const parts = [line, shade].filter((part) => part !== undefined);
  return parts.length === 0 ? "none" : parts.join(", ");
}
